 // A commitPipeline manages the stages of committing a set of mutations
@@ -300,6 +303,24 @@ func (p *commitPipeline) Commit(b *Batch, syncWAL bool, noSyncWait bool) error {
 		return nil
 	}

+	db := p.env.db
+	if db == nil {
+		db = b.db
+	}
+	trackDurability := syncWAL && db != nil && !db.opts.DisableWAL
+	var jobID int
+	var keyCount uint32
+	var batchSize int
+	var correlationID uint64
+	if trackDurability {
+		keyCount = b.Count()
+		batchSize = len(b.Repr())
+		correlationID = b.commitCorrelationID
+		if uint64(keyCount) != invalidBatchCount {
+			jobID = db.durability.registerJob()
+		}
+	}
+
 	commitStartTime := crtime.NowMono()
 	// Acquire semaphores.
 	p.commitQueueSem <- struct{}{}
@@ -317,15 +338,28 @@ func (p *commitPipeline) Commit(b *Batch, syncWAL bool, noSyncWait bool) error {
 	mem, err := p.prepare(b, syncWAL, noSyncWait)
 	if err != nil {
 		b.db = nil // prevent batch reuse on error
+		if trackDurability && jobID != 0 {
+			applyDuration := commitStartTime.Elapsed()
+			db.completeSyncCommit(jobID, b.SeqNum(), err, applyDuration, 0, correlationID, batchSize, keyCount)
+		}
 		// NB: we are not doing <-p.commitQueueSem since the batch is still
 		// sitting in the pending queue. We should consider fixing this by also
 		// removing the batch from the pending queue.
 		return err
 	}

+	seqNum := b.SeqNum()
+	if trackDurability {
+		batchSize = len(b.Repr())
+	}
+
 	// Apply the batch to the memtable.
 	if err := p.env.apply(b, mem); err != nil {
 		b.db = nil // prevent batch reuse on error
+		if trackDurability && jobID != 0 {
+			applyDuration := commitStartTime.Elapsed()
+			db.completeSyncCommit(jobID, seqNum, err, applyDuration, 0, correlationID, batchSize, keyCount)
+		}
 		// NB: we are not doing <-p.commitQueueSem since the batch is still
 		// sitting in the pending queue. We should consider fixing this by also
 		// removing the batch from the pending queue.
@@ -348,7 +382,42 @@ func (p *commitPipeline) Commit(b *Batch, syncWAL bool, noSyncWait bool) error {
 	// b.commitErr. We will read b.commitErr in Batch.SyncWait after the
 	// LogWriter is done writing.

-	b.commitStats.TotalDuration = commitStartTime.Elapsed()
+	totalElapsed := commitStartTime.Elapsed()
+	b.commitStats.TotalDuration = totalElapsed
+
+	if trackDurability && jobID != 0 {
+		if !noSyncWait {
+			syncDuration := b.commitStats.CommitWaitDuration
+			applyDuration := totalElapsed - syncDuration
+			if applyDuration <= 0 {
+				applyDuration = time.Nanosecond
+			}
+			if err == nil && syncDuration <= 0 {
+				syncDuration = time.Nanosecond
+			}
+			db.completeSyncCommit(jobID, seqNum, err, applyDuration, syncDuration, correlationID, batchSize, keyCount)
+		} else {
+			applyDuration := totalElapsed
+			if applyDuration <= 0 {
+				applyDuration = time.Nanosecond
+			}
+			syncStartTime := crtime.NowMono()
+			doneCh := make(chan struct{})
+			b.syncComplete = func() {
+				<-doneCh
+			}
+			go func() {
+				b.fsyncWait.Wait()
+				syncDuration := syncStartTime.Elapsed()
+				syncErr := b.commitErr
+				if syncErr == nil && syncDuration <= 0 {
+					syncDuration = time.Nanosecond
+				}
+				db.completeSyncCommit(jobID, seqNum, syncErr, applyDuration, syncDuration, correlationID, batchSize, keyCount)
+				close(doneCh)
+			}()
+		}
+	}

 	return err
 }
