+func (i BatchDurableInfo) SafeFormat(w redact.SafePrinter, _ rune) {
+	if i.Err != nil {
+		w.Printf("[JOB %d] batch durable seq=%d keys=%d size=%d corr=%d error: %s",
+			redact.Safe(i.JobID), i.SeqNum, redact.Safe(i.KeyCount), redact.Safe(i.BatchSize), redact.Safe(i.CorrelationID), i.Err)
+		return
+	}
+	w.Printf("[JOB %d] batch durable seq=%d keys=%d size=%d corr=%d apply=%s sync=%s",
+		redact.Safe(i.JobID), i.SeqNum, redact.Safe(i.KeyCount), redact.Safe(i.BatchSize), redact.Safe(i.CorrelationID),
+		redact.Safe(i.ApplyDuration.String()), redact.Safe(i.SyncDuration.String()))
+}
+
+func defaultBatchDurable(BatchDurableInfo) {}
+
+var defaultBatchDurablePtr = reflect.ValueOf(defaultBatchDurable).Pointer()
+
+func isBatchDurableConfigured(fn func(BatchDurableInfo)) bool {
+	if fn == nil {
+		return false
+	}
+	return reflect.ValueOf(fn).Pointer() != defaultBatchDurablePtr
+}
